  const streamIdTask = createTask<string | null>();

  const operationPromise = __flowRunEnvelope({
    url,
    input,
    init,
    sendChunk: (c) => channel.send(c),
    headers: streamId
      ? { ...headers, 'x-genkit-stream-id': streamId }
      : headers,
    abortSignal,
    responseCallback: (response) => {
